	config = {},

	-- Generator function
	generator = function(source)
		return function()
			local data_point = source.dp()
			if not data_point then
				return nil
			end

			-- Convert to absolute value
			data_point.value = math.abs(data_point.value)

			return data_point
		end
	end,
}
