		["th"] = "คัดลอกค่าของจุดข้อมูลแต่ละจุดไปยังป้ายกำกับในรูปแบบสตริง",
		["tr"] = "Her veri noktasının değerini dize olarak etiketine kopyalar.",
		["uk"] = "Копіює значення кожної точки даних у її мітку як рядок.",
		["vi"] = "Sao chép giá trị của mỗi điểm dữ liệu vào nhãn dưới dạng chuỗi.",
	},
	config = {
		enum {
			id = "mode",
			name = "_mode",
			options = {
				"_overwrite",
				"_prepend",
				"_append",
			},
			default = "_overwrite",
		},
	},

	generator = function(source, config)
		local mode = config and config.mode or "_overwrite"

		return function()
			local data_point = source.dp()
			if not data_point then
				return nil
			end

			local value_str = tostring(data_point.value)
			local existing = data_point.label or ""

			if mode == "_overwrite" then
				data_point.label = value_str
			elseif mode == "_prepend" then
				data_point.label = value_str .. existing
			elseif mode == "_append" then
				data_point.label = existing .. value_str
			end

			return data_point
		end
	end,
}
