			},
			default = "_hours",
		},
	},

	generator = function(source, config)
		local unit = config and config.unit or "_hours"
		local divisor = seconds_per_unit[unit]

		return function()
			local data_point = source.dp()
			if not data_point then
				return nil
			end

			data_point.value = data_point.value / divisor
			return data_point
		end
	end,
}
