	config = {},

	-- Generator function
	generator = function(source)
		return function()
			local data_point = source.dp()
			if not data_point then
				return nil
			end

			-- Swap label and note
			local temp = data_point.label
			data_point.label = data_point.note
			data_point.note = temp

			return data_point
		end
	end,
}
